import { z } from "zod";

/** Translation function type */
type TranslateFn = (key: string) => string;

/**
 * Create reset password schema with translated messages
 * @param t - Translation function from useTranslation hook
 */
export function createResetPasswordSchema(t: TranslateFn) {
    return z
        .object({
            newPassword: z
                .string()
                .min(8, t("validation.password.min"))
                .max(128, t("validation.password.max")),
            confirmPassword: z.string(),
        })
        .refine((data) => data.newPassword === data.confirmPassword, {
            message: t("validation.confirmPassword.mismatch"),
            path: ["confirmPassword"],
        });
}

/**
 * Reset password schema (for type inference)
 */
export const resetPasswordSchema = createResetPasswordSchema((key) => key);

export type ResetPasswordInput = z.infer<typeof resetPasswordSchema>;
```

```jac
import from "zod" { z }

type TranslateFn = Callable[[str], str];

def:pub createResetPasswordSchema(t: TranslateFn) -> object {
    return z
        .object({
            "newPassword": z.string().min(8, t("validation.password.min")).max(128, t("validation.password.max")),
            "confirmPassword": z.string()
        })
        .refine(
            lambda (data: dict[str, str]) -> bool {
                return data["newPassword"] == data["confirmPassword"];
            },
            {"message": t("validation.confirmPassword.mismatch"), "path": ["confirmPassword"]}
        );
}
