def iconClassName(className: str | None) -> str {
    parts = [x for x in ["agile-mobile-icon", className] if x];
    return " ".join(parts);
}

def iconStyle(style: dict[str, object] | None) -> dict[str, object] {
    base: dict[str, object] = {"verticalAlign": "-0.125em"};
    if style {
        return {**base, **style};
    }
    return base;
}

def:pub StarOutline(className: str | None = None, style: dict[str, object] | None = None) -> JsxElement {
    <svg
        width="1em"
        height="1em"
        viewBox="0 0 1024 1024"
        xmlns="http://www.w3.org/2000/svg"
        xmlnsXlink="http://www.w3.org/1999/xlink"
        style={iconStyle(style)}
        className={iconClassName(className)}
