    new Promise(resolve => {
      const changes = {}

      for (const [key, value] of Object.entries(items)) {
        const oldValue = localStorage.getItem(key)

        localStorage.setItem(key, value)

        changes[key] = {
          oldValue,
          newValue: value,
        }
      }

      fireStorageEvent(changes)

      resolve()
    }),
  remove: keys =>
