const DOT_SIZES: Record<SpinnerSize, string> = {
  xs: "size-1.5",
  sm: "size-2",
  md: "size-2.5",
  lg: "size-3",
  xl: "size-4",
  "2xl": "size-5",
  "3xl": "size-6",
