def:pub sortData(
    headers: list[SortHeader],
    data: list[dict[str, object]] | None,
    orderBy: str,
    order: str
) -> list[dict[str, object]] | None {
    orderByHeader: SortHeader = [header for header in headers if header.id == orderBy][0];
    transformFn: Callable[[object], object] = (
        orderByHeader.transformData as Callable[[object], object]
        if callable(orderByHeader.transformData)
        else (lambda (values: object) -> object { return values; })
    );
    if not data {
        return data;
    }
    transformedData: list[dict[str, object]] = [
        {**element, **{orderBy: transformFn(element[orderBy])}}
        for element in data
    ];
    sortedData: list[dict[str, object]] = [row for row in transformedData];
    for i = 0 while i < len(sortedData) with i += 1 {
        for j = (i + 1) while j < len(sortedData) with j += 1 {
            if sortedData[i][orderBy] > sortedData[j][orderBy] {
                tmp = sortedData[i];
                sortedData[i] = sortedData[j];
                sortedData[j] = tmp;
            }
        }
    }
    if order == "asc" {
        return sortedData;
    }
    return list(reversed(sortedData));
}
