    for a in range(n) {
        val = prefs[p2][si[a]];
        sum2Sq += val ** 2;
    }
    pSum = 0.0;
    for b in range(n) {
        pSum += prefs[p1][si[b]] * prefs[p2][si[b]];
    }
    num = pSum - (sum1 * sum2 / n);
    den = ((sum1Sq - (sum1 ** 2) / n) * (sum2Sq - (sum2 ** 2) / n)) ** 0.5;
    if den == 0 {
        return 0;
    }
    return num / den;
}
