import from "uuid" { v4 as uuid }
import from "@ninetailed/experience.js-shared" { buildPageEvent, NINETAILED_ANONYMOUS_ID_COOKIE, NinetailedApiClient, NinetailedRequestContext, Profile }

async def:pub getServerSideProfile(options: dict[str, object]) -> Profile {
    ctx = options["ctx"];
    cookies = options["cookies"] as dict[str, str];
    client = options["client"] as NinetailedApiClient;
    anonymousIdCookieString: str | None = cookies[NINETAILED_ANONYMOUS_ID_COOKIE] if NINETAILED_ANONYMOUS_ID_COOKIE in cookies else None;
    anonymousId = decodeURIComponent(anonymousIdCookieString) if anonymousIdCookieString else uuid();
    pageEvent = buildPageEvent({"ctx": ctx, "messageId": uuid(), "timestamp": Date.now(), "properties": {}});
    upsertResult = await client.upsertProfile({"events": [pageEvent], "profileId": anonymousId});
    profile = upsertResult.profile as Profile;
    return profile;
}
