  apolloClient: import('@apollo/client').ApolloClient<
    import('@apollo/client').NormalizedCacheObject
  >,
  linkId: string,
  linkAlias: string
) {
  apolloClient
    .mutate<
      CreateLinkUsageMetricMutation,
      CreateLinkUsageMetricMutationVariables
    >({
      mutation: CreateLinkUsageMetricDocument,
      variables: { linkId },
    })
    .then(() => {
      apolloLogger.info('metric.recorded', {
        alias: linkAlias,
        linkId,
      });
    })
    .catch((err: Error) => {
      apolloLogger.error('metric.failed', {
        alias: linkAlias,
        linkId,
        error: err.message,
      });
    });
