          ) : (
            <>
              {query === '' ? (
                <BaseTabList
                  tabLists={itemsToShow}
                  handleShowMoreItems={handleShowMoreItems}
                  isVisibleTabListHeader={isVisibleTabListHeader}
                  isMaxLength={isMaxLength}
