import from "react" { useCallback, useEffect, useState }
import from "./useReducedMotion" { useReducedMotion }

obj Presence {
    has mounted: bool;
    has leaving: bool;
}

def:pub usePresence(open: bool, duration: int = 220) -> Presence {
    reducedMotion = useReducedMotion();
    init = Presence(mounted=open, leaving=False);
    pair = useState(init);
    state = pair[0] as Presence;
    setState = pair[1] as Callable[[Presence | Callable[[Presence], Presence]], None];

    finish = useCallback(lambda { setState(Presence(mounted=False, leaving=False)); }, []);

    useEffect(lambda {
        if open {
            setState(Presence(mounted=True, leaving=False));
            return None;
        }
        if not state.mounted {
            return None;
        }
        if reducedMotion {
            finish();
            return None;
        }
        def updater(s: Presence) -> Presence {
            return Presence(mounted=s.mounted, leaving=True);
        }
        setState(updater);
        timer = setTimeout(finish, duration);
        return lambda { clearTimeout(timer); };
    }, [open, reducedMotion, duration, state.mounted, finish]);

    return state;
}
