import from "react" { useEffect }
import from "twilio-video" { LocalTrack, Room, connect as twilio_connect }

import from "../api" { getAccessToken }

def bind_room_disconnect(
    active_room: Room,
    set_room: Callable[[Room | None], None],
) -> Callable[[], None] {
    def on_disconnected() {
        set_room(None);
    }
    active_room.on("disconnected", on_disconnected);
    return lambda {
        active_room.off("disconnected", on_disconnected);
    };
}

def:pub useRoom(local_tracks: list[LocalTrack]) -> dict[str, object] {
    has room: Room | None = None;

    async def connect(username: str, roomname: str) {
        access_token = await getAccessToken(username, roomname);
        console.log(f"accessToken: {access_token}");
        room = await twilio_connect(access_token, {"tracks": local_tracks});
    }

    useEffect(lambda {
        if room {
            return bind_room_disconnect(room, lambda (next_room: Room | None) { room = next_room; });
        }
    }, [room]);

    return {"room": room, "connect": connect};
}
