      icon,
      iconColor,
      className,
      children,
      ...props
    },
    ref
  ) => {
    const { icon: listIcon, markerColor, hasCustomMarker } = useContext(ListContext);
    const itemIcon = icon ?? listIcon;
    const itemIconColor = iconColor ?? markerColor ?? "neutral";

    if (hasCustomMarker && itemIcon) {
