export function FolderActionMenu(props) {
  const { openDialog } = React.useContext(DialogContext);
  const {
    nodeId,
    readOnly,
    open,
    childUrls = [],
    onClose,
    onRemove,
    onCopy,
    onCut,
    onPaste,
    clipboard,
    menuProps = {},
  } = props;

  function handleClose() {
    onClose();
  }

