            hoursInterval,
            rowHeight,
            columnOffset: event.columnOffset,
            totalColumns: event.totalColumns,
          }),
        }}
        classNames={cssClasses}
        columnOffset={event.columnOffset}
        totalColumns={event.totalColumns}
      />
    );
  });
});

const DayColumnPreview = React.memo(function DayColumnPreview({
