import from "classnames" { default as classnames }

glob prefixCls = "fam-card";

obj:pub CardBodyProps {
    has className: str | None = None;
    has corner: bool | None = None;
}

def:pub CardBody(
    className: str | None = None,
    corner: bool | None = None,
    children: object | None = None,
    props: dict[str, object] | None = None,
) -> JsxElement {
    rest = props if props is not None else {};
    wrapCls = classnames(className, {
        f"{prefixCls}-body-corner": corner,
        f"{prefixCls}-body": not corner,
    });
    <div className={wrapCls} {**rest}>
        {if isinstance(children, list) {
            for n in children {
                <div className={f"{prefixCls}-body-item"}>{n}</div>
            }
        } else {
            children;
        }}
    </div>
