async def:pub submitApplication(userId: str, personalInfo: PersonalInfoForm) -> ApplicationResult {
    fetch_response = await supabase.from("applications").select("id").eq("user_id", userId) as SupabaseListResponse;
    existing = fetch_response.data;
    fetchError = fetch_response.error;
    if fetchError is not None {
        return ApplicationResult(success=False, message="خطا در بررسی اطلاعات قبلی");
    }
    if existing is not None and len(existing) > 0 {
        return ApplicationResult(success=False, message="شما قبلاً ثبت‌نام کرده‌اید");
    }
    insert_response = await supabase.from("applications").insert({
        "user_id": userId,
        "personal_info": personalInfo,
        "status": "pending",
    }) as SupabaseMutationResponse;
    insertError = insert_response.error;
    if insertError is not None {
        return ApplicationResult(success=False, message="خطا در ثبت درخواست");
    }
    return ApplicationResult(success=True, message="اطلاعات با موفقیت ثبت شد");
