            value={value}
            onChange={this.handleChange}
            indicatorColor="secondary"
            variant={isScrollable ? "scrollable" : undefined}
            scrollButtons="auto"
          >
            {data.map((item, index) => (
              <Tab key={`tab-${index}`} label={item.title} />
            ))}
          </MaterialTabs>
        </AppBar>

        {data.map((item, index) => {
          if (value === index) {
            return (
              <TabContainer key={`tabcontainer-${index}`}>
                {item.content}
              </TabContainer>
            );
          }
          return null;
        })}
      </div>
    );
  }
