         const { result } = renderHook(() => useNavigation(), { wrapper })

         act(() => {
            result.current.navigate('sessions', { sessionId: 'abc' })
         })

         expect(result.current.currentPage).toBe('sessions')
         expect(result.current.pageParams).toEqual({ sessionId: 'abc' })
      })

