   sessionTotalTokens: number | undefined
   contextTokens: number | undefined
}

function MessageRow({
   role,
   content,
   images,
   status,
   thinking,
   toolCalls,
   showThinking,
   senderName,
   timestamp,
   showTokens,
   usage,
   model,
   sessionTotalTokens,
   contextTokens,
}: MessageRowProps) {
