/**
 * One nearly-invisible dot tucked into a paragraph. Click it 5 times within
 * 6 seconds and we whisk you away to /secret. The Konami code (and typing
 * "joey") is handled site-wide by KonamiListener.
 */
export function EasterEggPixel() {
  const [, setCount] = useState(0);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const router = useRouter();

  const handleClick = () => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setCount(0), 6000);
    setCount((c) => {
      const next = c + 1;
      if (next >= 5) {
        router.push("/secret");
        return 0;
      }
      return next;
    });
  };

  return (
    <span
      role="button"
      aria-label="."
      tabIndex={-1}
      onClick={handleClick}
      className="invisible-pixel"
      title=""
    />
  );
}
