              <LinkTable
                baseUrl={baseUrl}
                links={links}
                isEditEnabled={canEdit}
                isDeleteEnabled={canDelete}
                onEdit={handleEdit}
                onShare={shareLink}
                onDelete={deleteLink}
              />
            </Suspense>
          )}
        </div>
      </div>
    </div>
  );
};

