  const request = context?.req as NextApiRequest;
  const { claims, user } = await getUserClaimsFromRequest(request);
  const common = await getCommonPageProps(context);

  return {
    props: {
      ...common,
      claims,
      userEmail: user?.email || null,
    },
  };
};
