    return query or {};
}

def:pub buildLocalizedPath(pathname: str, extraQuery: dict[str, object] | None = None) -> str {
    currentQuery = getSearchObj();
    merged = extraQuery if extraQuery else {};
    nextQuery = {**currentQuery, **merged};
    search = qs.stringify(nextQuery, {"skipEmptyString": True, "skipNull": True});
